ROW.COLUMN:
SELECT 
@MINER@.F_STRUCTURING_EN_RULE_B(@Lrf_Digits,                   
 @All_Trans_Src_Fl,             
  @MINER@.Lst(@Incl_Trans_Src_Lst),	          
  @All_Trans_Src_Fl,         
  @MINER@.Lst(@Incl_Jurisdictions_Lst),       
  @Look_Back_Period,             
  @MINER@.Lst(@Incl_MI_Trxn_Prdct_Type_Lst),       
  @MINER@.Lst(@Incl_Cash_Trxn_Prdct_Type_Lst),   
  @MINER@.Lst(@Incl_Wire_Trxn_Prdct_Type_Lst),
  @LE_R1,                        
  @LE_R2,                        
  @UE_R1,                        
  @UE_R2,                        
  @Min_Attempts
) as EXTRL_NTITY_SEQ_ID,
'BENE' as Job_type 
FROM dual

UNION ALL 

SELECT c.EXTRL_NTITY_SEQ_ID ,'BENE' as Job_type 
FROM 
(select * from @MINER@.DSVIEW118864094) c

SELECT 
@MINER@.F_STRUCTURING_EN_RULE_R(@Lrf_Digits,                   
  @All_Trans_Src_Fl,             
  @MINER@.Lst(@Incl_Trans_Src_Lst),	          
  @All_Jurisdictions_Fl,         
  @MINER@.Lst(@Incl_Jurisdictions_Lst),       
  @Look_Back_Period,             
  @MINER@.Lst(@Incl_MI_Trxn_Prdct_Type_Lst),       
  @MINER@.Lst(@Incl_Cash_Trxn_Prdct_Type_Lst),
  @MINER@.Lst(@Incl_Wire_Trxn_Prdct_Type_Lst),
  @LE_R1,                        
  @LE_R2,                        
  @UE_R1,                        
  @UE_R2,                        
  @Min_Attempts
) as EXTRL_NTITY_SEQ_ID,
'REM' as Job_type 
FROM dual

UNION ALL 

SELECT c.EXTRL_NTITY_SEQ_ID ,'REM' as Job_type 
FROM 
(select * from @MINER@.DSVIEW118864099) c
